INSERT INTO my_derby.horse_illness_catalog (ill_name, dvcd, source_name)
SELECT ill_name, dvcd, 'uploaded illName list; name-only classification'
FROM illness_rows
ON CONFLICT (ill_name) DO UPDATE SET
